import { promises as fs } from 'node:fs';
import * as path from 'node:path';
import { getBoard } from './board_registry';

export interface PeripheralTemplate {
  id: string;
  name: string;
  icon?: string;
  compatible: string[];
  signals: string[];
  kconfig?: string[];
  groups: PeripheralTemplateGroup[];
}

export interface PeripheralTemplateGroup {
  id: string;
  title: string;
  props: PeripheralProp[];
}

export interface PeripheralProp {
  key: string;
  type: string;
  default: unknown;
  dts?: boolean;
  kconfig?: string | null;
}

interface PeripheralTemplatesSnapshot {
  templates: PeripheralTemplate[];
}

interface FrontendPeripheral {
  name: string;
  display?: string;
  compatible?: string;
  dts_node?: string;
  signals?: string[];
  enabled?: boolean;
}

interface FrontendBoard {
  soc: string;
  package?: string;
  peripherals: FrontendPeripheral[];
}

let cachedTemplatesPath = '';
let cachedTemplates: PeripheralTemplate[] | null = null;

function snapshotPath(rootDir: string): string {
  return path.join(rootDir, 'backend_ts', 'src', 'generated', 'peripheral_templates.json');
}

async function loadTemplates(rootDir: string): Promise<PeripheralTemplate[]> {
  const nextPath = snapshotPath(rootDir);
  if (cachedTemplates && cachedTemplatesPath === nextPath) {
    return cachedTemplates;
  }

  const text = await fs.readFile(nextPath, 'utf8');
  const parsed = JSON.parse(text) as Partial<PeripheralTemplatesSnapshot>;
  if (!Array.isArray(parsed.templates)) {
    throw new Error(`Invalid peripheral template snapshot: ${nextPath}`);
  }

  cachedTemplatesPath = nextPath;
  cachedTemplates = parsed.templates as PeripheralTemplate[];
  return cachedTemplates;
}

export async function listPeripheralTemplates(rootDir: string): Promise<PeripheralTemplate[]> {
  return await loadTemplates(rootDir);
}

async function matchTemplate(rootDir: string, compatible: string): Promise<PeripheralTemplate | null> {
  const templates = await loadTemplates(rootDir);
  return templates.find((template) => template.compatible.includes(compatible)) ?? null;
}

export async function buildPeripheralInstances(rootDir: string, boardName: string): Promise<{
  board: string;
  soc: string;
  package: string;
  instances: Array<Record<string, unknown>>;
}> {
  const board = await getBoard(rootDir, boardName);
  if (!board || typeof board !== 'object') {
    throw new Error(`Board '${boardName}' not found`);
  }

  const frontend = board as FrontendBoard;
  const instances: Array<Record<string, unknown>> = [];
  for (const peripheral of frontend.peripherals ?? []) {
    const template = await matchTemplate(rootDir, peripheral.compatible ?? '');
    if (!template) {
      instances.push({
        instance: peripheral.name,
        display: peripheral.display ?? peripheral.name,
        compatible: peripheral.compatible ?? '',
        dts_node: peripheral.dts_node ?? '',
        signals: peripheral.signals ?? [],
        enabled: peripheral.enabled ?? false,
        template: null,
        icon: '⚙️',
        groups: [],
      });
      continue;
    }

    instances.push({
      instance: peripheral.name,
      display: peripheral.display ?? peripheral.name,
      compatible: peripheral.compatible ?? '',
      dts_node: peripheral.dts_node ?? '',
      signals: template.signals,
      enabled: peripheral.enabled ?? false,
      template: template.id,
      icon: template.icon ?? '⚙️',
      groups: template.groups,
    });
  }

  return {
    board: boardName,
    soc: frontend.soc,
    package: frontend.package ?? '',
    instances,
  };
}

export async function generatePeripheralConfig(
  rootDir: string,
  boardName: string,
  instanceValues: Record<string, Record<string, unknown>>,
): Promise<{ overlay: string; prj_conf: string }> {
  const board = await getBoard(rootDir, boardName);
  if (!board || typeof board !== 'object') {
    throw new Error(`Board '${boardName}' not found`);
  }

  const frontend = board as FrontendBoard;
  const overlayLines = [
    '/*',
    ' * Peripheral configuration overlay',
    ' * Generated by Zephyr Peripheral Configurator',
    ' */',
    '',
  ];
  const kconfigSet = new Set<string>();

  for (const [instanceName, values] of Object.entries(instanceValues)) {
    const boardPeripheral = frontend.peripherals.find((peripheral) => peripheral.name === instanceName);
    if (!boardPeripheral) {
      continue;
    }

    const template = await matchTemplate(rootDir, boardPeripheral.compatible ?? '');
    if (!template) {
      continue;
    }

    const dtsNode = boardPeripheral.dts_node ?? `&${instanceName}`;
    const dtsProps: string[] = [];
    for (const group of template.groups) {
      for (const prop of group.props) {
        if (!prop.dts) {
          continue;
        }
        const value = values[prop.key] ?? prop.default;
        if (prop.key === 'label' && !value) {
          continue;
        }
        if (prop.key === 'status') {
          dtsProps.push(`\tstatus = "${String(value)}";`);
        } else if (prop.key === 'label') {
          dtsProps.push(`\tlabel = "${String(value)}";`);
        } else if (prop.type === 'bool') {
          if (value) {
            dtsProps.push(`\t${prop.key};`);
          }
        } else if (prop.type === 'int') {
          dtsProps.push(`\t${prop.key} = <${value}>;`);
        } else if (prop.type === 'string') {
          dtsProps.push(`\t${prop.key} = "${String(value)}";`);
        } else if (prop.type === 'choice') {
          if (typeof value === 'number') {
            dtsProps.push(`\t${prop.key} = <${Math.trunc(value)}>;`);
          } else {
            dtsProps.push(`\t${prop.key} = "${String(value)}";`);
          }
        }
      }
    }

    if (dtsProps.length > 0) {
      overlayLines.push(`${dtsNode} {`);
      overlayLines.push(...dtsProps);
      overlayLines.push('};');
      overlayLines.push('');
    }

    for (const baseKconfig of template.kconfig ?? []) {
      kconfigSet.add(baseKconfig);
    }
    for (const group of template.groups) {
      for (const prop of group.props) {
        if (!prop.kconfig) {
          continue;
        }
        const value = values[prop.key] ?? prop.default;
        if (prop.type === 'bool') {
          kconfigSet.add(`${prop.kconfig}=${value ? 'y' : 'n'}`);
        } else if (prop.type === 'int') {
          kconfigSet.add(`${prop.kconfig}=${value}`);
        } else {
          kconfigSet.add(`${prop.kconfig}="${String(value)}"`);
        }
      }
    }
  }

  const kconfigLines = [
    '# --- Peripheral configuration -----------------------------------',
    '# Generated by Zephyr Peripheral Configurator',
    '',
  ];
  const sortedKconfig = [...kconfigSet].sort();
  if (sortedKconfig.length > 0) {
    kconfigLines.push(...sortedKconfig);
  } else {
    kconfigLines.push('# (no Kconfig changes)');
  }

  return {
    overlay: overlayLines.join('\n'),
    prj_conf: kconfigLines.join('\n'),
  };
}